export const ALL_TEAMS: StaticTeamData[] = [
  ...NBA, ...NFL, ...NHL, ...MLB, ...NCAA, ...EPL, ...MLS,
];

export function getLeagueStaticTeams(league: string): StaticTeamData[] {
  const map: Record<string, StaticTeamData[]> = {
    NBA, NFL, NHL, MLB, NCAA,
    FIFA: EPL,
    MLS,
  };
  return map[league] ?? [];
}

export function getStaticTeamById(id: string): StaticTeamData | undefined {
  return ALL_TEAMS.find(t => t.id === id || t.espnId === id || t.tsdbId === id);
}

export function findStaticTeam(league: string, nameOrAbbr: string): StaticTeamData | undefined {
  if (!nameOrAbbr) return undefined;
  const teams = getLeagueStaticTeams(league);
  const q = nameOrAbbr.toLowerCase();
  return teams.find(t =>
    t.name.toLowerCase() === q ||
    t.nickname.toLowerCase() === q ||
    t.abbreviation.toLowerCase() === q ||
    t.location.toLowerCase() === q ||
    t.name.toLowerCase().includes(q) ||
    q.includes(t.nickname.toLowerCase())
  );
}
